using System.ComponentModel;
using System.Net.Http.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool("fetch_data"), Description("Fetches data from the external API for a given resource path.")]
    public static async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        ILogger<ApiFetchTool> logger,
        [Description("The API resource path to fetch (e.g. \"users/1\")")] string path)
    {
        var client = httpClientFactory.CreateClient("ExternalApi");

        logger.LogInformation("Fetching external API resource: {Path}", path);

        var response = await client.GetAsync(path);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync();
        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a prompt to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Optional target length (e.g. \"2 sentences\")")] string? length = null)
    {
        var instruction = length is not null
            ? $"Summarize the following text in approximately {length}:"
            : "Summarize the following text concisely:";

        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content { Type = "text", Text = $"{instruction}\n\n{text}" }
            }
        ];
    }
}

