using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt(Name = "summarize"), Description("Generates a prompt to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Optional target length (e.g. \"2 sentences\")")] string? length = null)
    {
        var instruction = length is not null
            ? $"Summarize the following text in approximately {length}:"
            : "Summarize the following text concisely:";

        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new TextContentBlock { Text = $"{instruction}\n\n{text}" }
            }
        ];
    }
}

